module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
    reg clk_div;

    parameter NUM_DIV = 6;

    reg [2:0] counter;

    always @(posedge clk) begin
        if (rst_n) begin
            counter <= 3'd0;
            clk_div <= 1'b0;
        end else begin
            if (counter == NUM_DIV - 1) begin
                counter <= 3'd0;
                clk_div <= ~clk_div;
            end else begin
                counter <= counter + 3'd1;
            end
        end
    end

    assign clk_div = (counter < (NUM_DIV / 2)) ? 1'b1 : 1'b0;

endmodule

